    <section class="overflow-x-auto rounded-2xl border bg-white p-5"><h2 class="mb-3 text-lg font-bold">Bảng dữ liệu báo cáo biến động</h2><table class="w-full min-w-[900px] text-left text-sm"><thead class="bg-slate-50"><tr><th class="p-3">Thời gian</th><th class="p-3">Vật tư</th><th class="p-3">Loại biến động</th><th class="p-3">Số lượng</th><th class="p-3">Tham chiếu</th><th class="p-3">Người thực hiện</th></tr></thead><tbody>@forelse($rows as $row)<tr class="border-t"><td class="p-3">{{ $row->created_at?->format('d/m/Y H:i') }}</td><td class="p-3">{{ $row->material?->code }} — {{ $row->material?->name }}</td><td class="p-3">{{ ['IN'=>'Tăng','OUT'=>'Giảm','ADJUST'=>'Điều chỉnh'][$row->type]??$row->type }}</td><td class="p-3">{{ $row->quantity }}</td><td class="p-3">{{ $row->reference?:'—' }}</td><td class="p-3">{{ $row->user?->name }}</td></tr>@empty<tr><td colspan="6" class="p-6 text-center text-slate-500">Chưa có dữ liệu biến động.</td></tr>@endforelse</tbody></table><div class="mt-3">{{ $rows->links() }}</div></section>
    <div id="export-panel" class="fixed inset-0 z-50 hidden items-center justify-center bg-black/50 p-4"><div class="w-full max-w-md rounded-2xl border bg-white p-5 shadow-xl"><div class="flex items-center justify-between"><h2 class="text-lg font-bold">Xuất báo cáo</h2><button type="button" id="close-export-panel" class="text-xl">×</button></div><form method="GET" action="{{ route('inventory.reports.word.templates') }}" class="mt-4"><label class="block text-sm font-semibold">Loại báo cáo<select name="report_type" class="mt-1 block w-full rounded-lg border px-3 py-2.5"><option value="summary">Thống kê thực lực hiện có</option><option value="unit">Thống kê thực lực vật tư theo đơn vị</option><option value="movement">Thống kê tăng, giảm thực lực vật tư</option><option value="warehouse">Báo cáo kho vật tư</option><option value="transfer">Báo cáo quyết định điều động</option><option value="recall">Báo cáo quyết định thu hồi</option><option value="repair">Báo cáo vật tư hư hại và sửa chữa</option><option value="update-log">Cập nhật vật tư</option></select></label><label id="unit-filter-modal" class="mt-3 hidden block text-sm font-semibold">Đơn vị quản lý<select name="unit_id" class="mt-1 block w-full rounded-lg border px-3 py-2.5"><option value="">Chọn đơn vị</option>@foreach($units ?? [] as $unit)<option value="{{ $unit->id }}">{{ $unit->name }}</option>@endforeach</select></label><div class="mt-4 rounded-lg border p-3 text-sm"><p class="mb-2 font-semibold">Phạm vi</p><label class="block"><input type="radio" name="scope" value="position" checked> Theo vị trí lắp đặt</label><label class="mt-2 block"><input type="radio" name="scope" value="all"> Tổng hợp toàn bộ phòng/tòa</label></div><div class="mt-5 flex justify-end gap-2"><button type="button" id="cancel-export-panel" class="rounded-lg border px-4 py-2">Hủy</button><button class="rounded-lg bg-slate-900 px-4 py-2 font-bold text-white">Xuất Word</button></div></form></div></div>
