<script>const exportPanel=document.getElementById('export-panel'),reportType=document.querySelector('#export-panel select[name="report_type"]'),unitFilter=document.getElementById('unit-filter-modal');document.getElementById('open-export-panel')?.addEventListener('click',()=>exportPanel?.classList.replace('hidden','flex'));const closeExport=()=>exportPanel?.classList.replace('flex','hidden');document.getElementById('close-export-panel')?.addEventListener('click',closeExport);document.getElementById('cancel-export-panel')?.addEventListener('click',closeExport);const updateUnit=()=>unitFilter?.classList.toggle('hidden',reportType?.value!=='unit');reportType?.addEventListener('change',updateUnit);updateUnit();</script>
